      await runTests();
      console.log('✅ Self-healed successfully');
      await commitFix(faultyFile, fix, error);
    } catch (testError) {
      // Healing failed, try more aggressive approach
      await this.aggressiveHeal(faultyFile, error);
    }
  }
};
